def create_copy_all():
    output = [[0]*11 for _ in range(11)]

    # Top-left quadrant (already correct)
    for r in range(5):
        for c in range(5):
            output[r][c] = test_input[r][c]

    # Copy TL to top-right (direct copy, no mirror)
    for r in range(5):
        for c in range(5):
            output[r][6+c] = test_input[r][c]

    # Copy TL to bottom-left  
    for r in range(5):
        for c in range(5):
            output[6+r][c] = test_input[r][c]

    # Copy TL to bottom-right (direct copy)
    for r in range(5):
        for c in range(5):
            output[6+r][6+c] = test_input[r][c]

    # Preserve barriers
    for c in range(11):
        output[5][c] = 4
    for r in range(11):
        output[r][5] = 4

    return output

